// 简化版的wangEditor兼容库，用于处理基本的富文本编辑功能
(function (global, factory) {
  typeof exports === 'object' && typeof module !== 'undefined' ? module.exports = factory() :
  typeof define === 'function' && define.amd ? define(factory) :
  (global.wangEditor = factory());
}(this, (function () { 'use strict';

  // 简化版的wangEditor构造函数
  function WangEditor(selector) {
    if (!(this instanceof WangEditor)) {
      return new WangEditor(selector);
    }
    
    // 获取目标元素
    if (typeof selector === 'string') {
      this.elem = document.querySelector(selector);
    } else {
      this.elem = selector;
    }
    
    if (!this.elem) {
      throw new Error('找不到编辑器容器元素');
    }
    
    this.config = {
      zIndex: 100,
      height: 200,
      placeholder: '在这里输入博客内容...',
      menus: [
        'head',
        'bold',
        'fontSize',
        'fontName',
        'italic',
        'underline',
        'strikeThrough',
        'indent',
        'lineHeight',
        'foreColor',
        'backColor',
        'link',
        'list',
        'justify',
        'quote',
        'emoticon',
        'image',
        'table',
        'code',
        'undo',
        'redo'
      ],
      uploadImgMaxSize: 5 * 1024 * 1024,
      uploadImgAccept: ['jpg', 'jpeg', 'png', 'gif', 'bmp']
    };
    
    this.txt = {
      html: function(content) {
        if (typeof content !== 'undefined') {
          // 设置内容
          this.elem.innerHTML = content;
        } else {
          // 获取内容
          return this.elem.innerHTML;
        }
      }.bind(this),
      clear: function() {
        this.elem.innerHTML = '';
      }.bind(this)
    };
  }

  // 创建编辑器方法
  WangEditor.prototype.create = function() {
    // 创建一个简单的富文本编辑器
    this.elem.contentEditable = true;
    this.elem.style.border = '1px solid #ccc';
    this.elem.style.borderRadius = '4px';
    this.elem.style.padding = '10px';
    this.elem.style.outline = 'none';
    this.elem.style.minHeight = (this.config.height || 200) + 'px';
    this.elem.style.backgroundColor = '#fff';
    
    // 设置占位符
    if (this.config.placeholder) {
      this.elem.setAttribute('placeholder', this.config.placeholder);
      this.elem.addEventListener('focus', function() {
        if (this.innerHTML === this.getAttribute('placeholder')) {
          this.innerHTML = '';
          this.style.color = '';
        }
      });
      this.elem.addEventListener('blur', function() {
        if (!this.innerHTML.trim()) {
          this.innerHTML = this.getAttribute('placeholder');
          this.style.color = '#999';
        }
      });
      
      // 初始化时显示占位符
      if (!this.elem.innerHTML.trim()) {
        this.elem.innerHTML = this.config.placeholder;
        this.elem.style.color = '#999';
      }
    }
    
    // 添加基本的编辑功能
    this.elem.addEventListener('input', function() {
      // 确保占位符正确显示
      if (!this.innerHTML.trim()) {
        this.innerHTML = this.getAttribute('placeholder');
        this.style.color = '#999';
      } else {
        this.style.color = '';
      }
    });
  };

  // 添加静态属性
  WangEditor.version = '4.7.15';

  return WangEditor;

})));